syntax:
template <typename T>
ReturnType functionName(T arg);

// General template
template <typename T>
ReturnType functionName(T arg) {
    // generic implementation
}

// Specialization for a specific type
template <> 
ReturnType functionName<int>(int arg) {
    // specialized implementation for int
}

code_example:
#include <iostream>
template <typename T>
void process(T value) {
    std::cout << "Generic process: " << value << std::endl;
}
// Specialization for int type
template <>
void process(int value) {
    std::cout << "Specialized process for int: " << value << std::endl;
}
int main() {
    process(3.14); // calls generic template
    process(42);   // calls specialized template for int
    return 0;
}
